sysevent_in_email_action.script:
(function runAction(current, event, email, logger, classifier) {
    var lines = email.body_text.toString().split('\n');
    var patientId, doctorId, apptDate, department;

    lines.forEach(function(line) {
        line = line.trim();
        if (line.startsWith("Patient ID:")) patientId = line.split("Patient ID:")[1].trim();
        if (line.startsWith("Doctor ID:")) doctorId = line.split("Doctor ID:")[1].trim();
        if (line.startsWith("Date:")) apptDate = line.split("Date:")[1].trim();
        if (line.startsWith("Department:")) department = line.split("Department:")[1].trim();
    });

    // Validate required fields
    if (!patientId || !doctorId || !apptDate || !department) {
        gs.error("Missing required fields in the email body.");
        return;
    }

    // Look up Patient
    var patientGR = new GlideRecord('u_patient_record');
    patientGR.addQuery('u_number', patientId);
    patientGR.query();
    if (!patientGR.next()) {
        gs.error("Patient not found for ID: " + patientId);
        return;
    }

    // Look up Doctor
    var doctorGR = new GlideRecord('u_doctor_record');
    doctorGR.addQuery('number', doctorId);
    doctorGR.query();
    if (!doctorGR.next()) {
        gs.error("Doctor not found for ID: " + doctorId);
        return;
    }

    // Create Appointment
    var appt = new GlideRecord('u_appointment');
    appt.initialize();
    appt.u_patient_id = patientGR.sys_id;
    appt.u_doctor_id = doctorGR.sys_id;
    appt.u_appointment_date = apptDate;
    appt.u_department = department;
    //appt.u_statis = 'Scheduled'; // Set default status
    appt.short_description = email.subject || 'Scheduled via Email';
    appt.insert();

    // Associate email with record
    sys_email.instance = appt.sys_id;
    sys_email.target_table = appt.getTableName();
    event.state = 'stop_processing';

    gs.info("Appointment created successfully for Patient: " + patientId + ", Doctor: " + doctorId);
})(current, event, email, logger, classifier);
